{
  "name": "opencode-token-board",
  "version": "1.0.1",
  "description": "Real-time token usage, cache analytics & performance dashboard plugin for OpenCode V2",
  "type": "module",
  "main": "./dist/server.js",
  "types": "./dist/server.d.ts",
  "exports": {
    ".": {
      "types": "./dist/server.d.ts",
      "import": "./dist/server.js"
    },
    "./tui": {
      "types": "./dist/tui.d.ts",
      "import": "./dist/tui.js"
    },
    "./server": {
      "types": "./dist/server.d.ts",
      "import": "./dist/server.js"
    },
    "./package.json": "./package.json"
  },
  "files": [
    "dist"
  ],
  "sideEffects": false,
  "engines": {
    "node": ">=18"
  },
  "scripts": {
    "build": "tsc && node build.tui.mjs",
    "typecheck": "tsc --noEmit",
    "test": "npm run test:queries && npm run test:stats && npm run test:perf",
    "test:queries": "esbuild scripts/test-queries.ts --bundle --platform=node --format=esm --outfile=node_modules/.cache/tw-tests/test-queries.mjs && node node_modules/.cache/tw-tests/test-queries.mjs",
    "test:stats": "esbuild scripts/test-stats-upgrade.ts --bundle --platform=node --format=esm --outfile=node_modules/.cache/tw-tests/test-stats-upgrade.mjs && node node_modules/.cache/tw-tests/test-stats-upgrade.mjs && node node_modules/.cache/tw-tests/test-stats-upgrade.mjs --v2",
    "test:perf": "esbuild scripts/check-perf-real.ts --bundle --platform=node --format=esm --outfile=node_modules/.cache/tw-tests/check-perf-real.mjs && node node_modules/.cache/tw-tests/check-perf-real.mjs",
    "release:check": "node ./scripts/publish-check.mjs",
    "prepublishOnly": "npm run build"
  },
  "keywords": [
    "opencode",
    "opencode-v2",
    "plugin",
    "tokens",
    "usage",
    "stats",
    "analytics",
    "tui"
  ],
  "license": "MIT",
  "author": "zhuzhutai",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/zhuzhutai/opencode-token-board.git"
  },
  "bugs": {
    "url": "https://github.com/zhuzhutai/opencode-token-board/issues"
  },
  "homepage": "https://github.com/zhuzhutai/opencode-token-board#readme",
  "dependencies": {
    "@opencode/plugin": "2.0.29"
  },
  "peerDependencies": {
    "@opentui/core": ">=0.5.17",
    "@opentui/solid": ">=0.5.17",
    "solid-js": ">=1.9.0"
  },
  "devDependencies": {
    "@opencode/client": "2.0.29",
    "@opencode/theme": "^2.0.29",
    "@opentui/core": "0.6.6",
    "@opentui/solid": "0.6.6",
    "@types/node": "^22.0.0",
    "esbuild": "^0.25.0",
    "esbuild-plugin-solid": "^0.5.0",
    "solid-js": "1.9.12",
    "typescript": "^5.7.0"
  },
  "publishConfig": {
    "access": "public"
  }
}
